function earSchedMetre(q,t0){const barLen=q.len/4,nb=Math.max(4,Math.round((q.dur||10)/barLen),Math.ceil(10/barLen-1e-9)),lead=.6,t=t0-ELPRE+lead,ev=[],beats=[],n={};
 for(let b=0;b<nb;b++){const k=b%4;q.ev.forEach(e=>{if(e.t>=k*barLen-1e-6&&e.t<(k+1)*barLen-1e-6)ev.push({t:b*barLen+e.t-k*barLen,a:e.a,bar:b+1})})}
 ev.push({t:nb*barLen,a:2,bar:nb+1});
 ev.forEach(e=>{earClick(t+e.t,e.a);if(e.a>=2)c2Tone(43,t+e.t,.25,0);e.t+=lead;e.kind=['sub','beat','accent','down'][e.a+1];if(e.a>=0){n[e.bar]=(n[e.bar]||0)+1;beats.push({t:e.t,a:e.a,bar:e.bar,beat:n[e.bar],kind:e.kind})}});
 // the level is evened out for how much sounds each second (relative energy of a downbeat, an accent, a beat and a subdivision), so 2/4 and 5/4 sit at the same loudness
 const E={2:160,1:10,0:3.1,'-1':1},pw=ev.reduce((s,e)=>s+E[e.a],0)/(nb*barLen);
 return{end:t+nb*barLen+.25,lead,beats,events:ev,gain:Math.sqrt(120/pw)*Math.pow(q.bpm/90,.45)}}
/* rhythm (EL-4): one bar of count-in on the woodblock, then the rhythm; the pulse goes on (switchable off); 72 or 100 crotchets a minute.
   Rung 1 is clapped; from rung 2 a tone, because a clap can't show a held note against a note and a rest. */
function earRhyBpm(l){return EAR.rhy.bpm||(l===1?72:100)}
function earSchedRhy(q,t0,o={}){const bpm=o.bpm||earRhyBpm(q.lvl||earLvl()),pulse=o.pulse!==undefined?o.pulse:EAR.rhy.pulse,clap=o.clap!==undefined?o.clap:(q.lvl||earLvl())===1,beat=60/bpm,sq=beat/4,lead=.15,ev=[];
 let t=t0+lead;for(let i=0;i<4;i++)elBlock(t+i*beat,!i);t+=4*beat;let p=0;
 q.a.forEach(k=>RCELL[k].u.forEach(([d,rest])=>{if(!rest){if(clap)elClap(t+p*sq);else elRhyNote(t+p*sq,d*sq);ev.push({t:t+p*sq-t0+ELPRE,d:d*sq,u:p,du:d});if(o.follow&&!ELT.rendering){const u0=p;PLAY.timers.push(setTimeout(()=>earRhyCaret(u0),Math.max(0,(t+p*sq-ac().currentTime)*1000)))}}p+=d}));
 if(pulse)for(let i=0;i<p/4;i++)elBlock(t+i*beat,false);
 // claps are short, so a bar of two minims would sound much quieter than a bar of quavers: the clapped level follows the number of claps
