function earSchedReplay(q,variant,t0,o){let t=t0,end=t0;const O=(o&&o.o)||[];
 if(q.d==='qual'){const n=q.notes;
  if(variant==='qab'){const g=EAR.res&&EAR.res.given,gn=earQualNotes(q.root,g,q.reg);gn.forEach(m=>pn(m,t,1.4));t+=1.9;n.forEach(m=>pn(m,t,1.6));end=t+1.6}
  else{const i={q3:1,q5:2,q7:3}[variant];pn(n[0],t,1.1);pn(n[i],t,1.1);t+=1.5;n.forEach(m=>pn(m,t,1.6));end=t+1.6}}
 else if(q.d==='cad'){const n=q.a==='cad64'?3:2,src=q.ch.slice(-n);src.forEach((c,i)=>{const last=i===src.length-1;c.forEach(m=>pn(m,t,last?2.2:1.6));end=t+(last?2.2:1.6);t+=1.6})}
 else if(q.d==='bass'){const k=O[0]||1,pair=[q.ch[k-1],q.ch[k]];pair.forEach((c,i)=>{c.forEach(m=>pn(m,t,i?1.8:1.2));end=t+(i?1.8:1.2);t+=1.4})}
 else if(q.d==='mel'){const G=[q.a[0],...(EAR.res&&EAR.res.given||[])],k=Math.max(1,O[0]||1),i0=Math.max(0,k-1),i1=Math.min(q.a.length-1,k+1),say=(arr)=>{for(let i=i0;i<=i1;i++){if(arr[i]!==undefined)c2Tone(eSolMidi(eSolParse(arr[i]),q.key),t+(i-i0)*.65,.6,1)}end=t+(i1-i0)*.65+.6;t+=(i1-i0+1)*.65+.7};
  say(G);say(q.a)}
 else if(q.d==='blind'){const m=AN.meta[q.score],from=Math.max(q.s,q.e-3500);m.events.forEach(([ms,p,d])=>{if(ms>=from-5&&ms<q.e-5){const st=t+Math.max(0,ms-from)/1000,du=Math.min(d,q.e-ms)/1000;tone(p,st,'piano',1,du);end=Math.max(end,st+du)}})}
 return{end:end+.05,lead:ELPRE}}
