  if(e.key===' '&&busy()){const a=document.activeElement,tag=a&&a.tagName;if(!/INPUT|TEXTAREA|SELECT/.test(tag)&&!(a&&a.isContentEditable)){e.preventDefault();stopAll()}}});
 document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.id==='tStop')return;
  if(b.dataset.playing&&!busy()){PK=null;unmark()}
  if(b.dataset.playing||(busy()&&PK&&sig(b)===PK)){e.stopImmediatePropagation();e.preventDefault();if(performance.now()<PLAY.guard)return;stopAll();PK=null;unmark();return}
  if(!/^\s*▶/.test(b.textContent))return;
  if(busy()&&performance.now()>=PLAY.guard)stopAll();unmark();const key=sig(b);
  setTimeout(()=>{if(!busy())return;PK=key;const m=b.isConnected&&/^\s*▶/.test(b.textContent)?b:find();if(m)mark(m)},40)},true)})();
/* remember the stage between visits */
(()=>{try{let l=+localStorage.getItem('cjg_level');if(!(l>=1&&l<=7)){const o=+localStorage.getItem('cjg_stage');l=LVMIG[o]||0;if(l)localStorage.setItem('cjg_level',l)}if(l>=1&&l<=7){S.level=l;document.querySelectorAll('#lvl button').forEach(b=>b.classList.toggle('on',+b.dataset.l===l))}}catch(e){}})();
/* journal drafts are kept as you type */
(()=>{try{const D=JSON.parse(localStorage.getItem('cjg_jdraft')||'[]');[1,2,3,4].forEach(i=>{const t=$('j'+i);if(!t)return;if(D[i-1]&&!t.value)t.value=D[i-1];t.addEventListener('input',()=>{try{localStorage.setItem('cjg_jdraft',JSON.stringify([1,2,3,4].map(k=>$('j'+k)?$('j'+k).value:'')))}catch(e){}})})}catch(e){}})();
render();renderLog();applyRoute(location.hash.slice(1));termInit();
